<template><div class="app-container"><el-card><template #header>系统参数</template><el-table :data="params"><el-table-column prop="paramKey" label="参数键" /><el-table-column prop="paramValue" label="参数值" /><el-table-column prop="description" label="说明" /><el-table-column label="操作" width="100"><template #default="scope"><el-button link type="primary" icon="Edit" @click="handleEdit(scope.row)">编辑</el-button></template></el-table-column></el-table><el-dialog title="编辑参数" v-model="dialogVisible" width="400px"><el-form :model="editParam"><el-form-item label="参数值"><el-input v-model="editParam.paramValue" /></el-form-item></el-form><template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" @click="dialogVisible=false;ElMessage.success('参数已更新')">确定</el-button></template></el-dialog></el-card></div></template>
<script setup lang="ts">import { ref, reactive } from 'vue';import { ElMessage } from 'element-plus';const dialogVisible=ref(false), editParam=reactive({paramKey:'',paramValue:''});const params=[{paramKey:'cpq.default.currency',paramValue:'CNY',description:'默认币种'},{paramKey:'cpq.quote.auto.number',paramValue:'true',description:'报价单号自动生成'},{paramKey:'cpq.approval.timeout.hours',paramValue:'48',description:'审批超时(小时)'}];const handleEdit=(row:any)=>{editParam.paramKey=row.paramKey;editParam.paramValue=row.paramValue;dialogVisible.value=true}</script>
